<script setup lang="ts">useHead({title:'مقایسه محصولات'});const{api,media}=useShopApi(),{ids,toggle}=useCompare();const{data,refresh}=await useAsyncData('compare-products',()=>ids.value.length>=2?api<any[]>('/catalog/compare',{query:{ids:ids.value.join(',')}}):Promise.resolve([]),{watch:[ids]});const money=(v=0)=>new Intl.NumberFormat('fa-IR').format(v);async function remove(id:number){toggle(id);await refresh()}</script>
<template><div class="mx-auto max-w-7xl px-4 py-10"><h1 class="text-2xl font-black">مقایسه محصولات</h1><p class="mt-2 text-sm text-slate-400">حداکثر چهار محصول را کنار هم بررسی کنید.</p><div v-if="data?.length" class="mt-7 overflow-x-auto"><table class="w-full min-w-[700px] table-fixed overflow-hidden rounded-2xl border bg-white text-sm"><tbody><tr><th class="w-40 bg-slate-50 p-4">محصول</th><td v-for="p in data" :key="p.id" class="border-r p-4 text-center"><img v-if="p.media?.[0]" :src="media(p.media[0].path)" class="mx-auto aspect-square w-36 rounded-xl object-cover"><p class="mt-3 font-black">{{p.title}}</p><button class="mt-2 text-xs text-rose-600" @click="remove(p.id)">حذف از مقایسه</button></td></tr><tr><th class="bg-slate-50 p-4">برند</th><td v-for="p in data" :key="p.id" class="border-r p-4 text-center">{{p.brand?.title||'—'}}</td></tr><tr><th class="bg-slate-50 p-4">قیمت پایه</th><td v-for="p in data" :key="p.id" class="border-r p-4 text-center font-black">{{money(p.variants?.[0]?.price)}} تومان</td></tr><tr><th class="bg-slate-50 p-4">تنوع‌ها</th><td v-for="p in data" :key="p.id" class="border-r p-4 text-center">{{p.variants?.length}}</td></tr><tr><th class="bg-slate-50 p-4">وضعیت</th><td v-for="p in data" :key="p.id" class="border-r p-4 text-center">{{p.variants?.some((v:any)=>v.stock)?'موجود':'ناموجود'}}</td></tr></tbody></table></div><div v-else class="mt-7 rounded-2xl border border-dashed bg-white p-16 text-center"><p class="font-black">حداقل دو محصول انتخاب کنید</p><p class="mt-2 text-sm text-slate-400">از آیکن مقایسه روی کارت محصولات استفاده کنید.</p><NuxtLink to="/products" class="mt-5 inline-block rounded-xl bg-brand-700 px-6 py-3 font-bold text-white">انتخاب محصول</NuxtLink></div></div></template>
